# box::use pkg + module at top; target reports globals / search path / envir where it runs
# Generated by ../../04-targets.R. Run here: Rscript -e 'targets::tar_make()'  (USE_CREW=true for crew)
library(targets)
if (Sys.getenv("USE_CREW") == "true")
  tar_option_set(controller = crew::crew_controller_local(name = "crew", workers = 2, seconds_idle = 10))
tar_option_set(error = "continue")   # every target reports its own outcome

options(box.path = getwd())
box::use(dplyr[mutate])
box::use(mods/tfuns)
add_x <- function(d) mutate(d, x = var1 * 2)

list(
  tar_target(out, paste(
    "ran on:", Sys.getenv("CREW_CONTROLLER", "main process"),
    "| globals:", toString(ls(globalenv())),
    "| search() has:", toString(grep("^mod:|dplyr", search(), value = TRUE)),
    "| envir:", environmentName(tar_option_get("envir"))))
)
